 // A failed scan is a capture rejection, not a whole-interval no-root proof.
 const auto&q=op.q;auto srcq=op.observation.query;Vec2<double>u,v;srcq->point(op.branch.lower,&u);srcq->point(op.branch.upper,&v);const double dx=v[0]-u[0],dy=v[1]-u[1],d2=dx*dx+dy*dy;
 double nearest_cost=1e300;std::array<double,3>nearest{};Vec2<double>nearest_uv{};
 auto value=[&](double s,std::array<double,3>*x,double*g){auto rr=q.model->project_rs(q.layout,s,op.observation.uv[1]);if(!rr.valid)return false;auto uv=q.model->predict_explicit(q.layout,s,rr.row,p.data());if(!uv.valid()||!q.model->visibility(q.layout,s,rr.row,p.data()).visible())return false;for(int kind:{5,6})if(q.model->measurement_domain(q.layout,s,p.data(),kind)>1e-8)return false;double ec=std::pow(uv.uv[0]-op.observation.uv[0],2)+std::pow(uv.uv[1]-op.observation.uv[1],2);if(ec<nearest_cost){nearest_cost=ec;nearest={s,rr.row,op.branch.measured_alpha};nearest_uv=uv.uv;}double a=op.branch.lower+((uv.uv[0]-u[0])*dx+(uv.uv[1]-u[1])*dy)/d2*(op.branch.upper-op.branch.lower);*x={s,rr.row,a};*g=((uv.uv[0]-u[0])*(-dy)+(uv.uv[1]-u[1])*dx)/std::sqrt(d2);return std::isfinite(*g);};
 Root best;best.status="coarse_physical_capture_reject";double best_error=1e300;
 auto retain=[&](const std::array<double,3>&x){if(x[2]<op.branch.lower||x[2]>op.branch.upper)return;auto rr=op.resolve(p,x[0],x[1],x[2]);if(!rr.valid)return;const auto e=std::hypot(rr.uv[0]-op.observation.uv[0],rr.uv[1]-op.observation.uv[1]);if(e<best_error){best=rr;best.status="valid_local_branch_after_coarse_physical_capture";best_error=e;}};
 for(const auto&iv:op.observation.station_intervals(*q.model,q.layout.path)){
  bool prev=false;std::array<double,3>last{};double glast=0;
  std::vector<double>seeds;for(int k=0;k<=32;++k)seeds.push_back(iv[0]+(iv[1]-iv[0])*k/32.);if(current_station>=iv[0]&&current_station<=iv[1])seeds.push_back(current_station);std::sort(seeds.begin(),seeds.end());
  for(double s:seeds){std::array<double,3>x{};double g=0;if(!value(s,&x,&g)){prev=false;continue;}if(std::abs(g)<1e-8)retain(x);if(prev&&glast*g<0){double lo=last[0],hi=s,glo=glast;std::array<double,3>z{};bool valid=true;for(int k=0;k<40;++k){double mid=.5*(lo+hi),gm=0;if(!value(mid,&z,&gm)){valid=false;break;}if(std::abs(gm)<1e-10)break;if(gm*glo<=0)hi=mid;else{lo=mid;glo=gm;}}if(valid)retain(z);}prev=true;last=x;glast=g;
  }
 }
 if(nearest_cost<1e299){
  auto initial=nearest;for(const auto&iv:op.observation.station_intervals(*q.model,q.layout.path))if(initial[0]>=iv[0]&&initial[0]<=iv[1]){double lo=std::max(iv[0],initial[0]-(iv[1]-iv[0])/32.),hi=std::min(iv[1],initial[0]+(iv[1]-iv[0])/32.);auto cost=[&](double s){std::array<double,3>z{};double g=0;if(!value(s,&z,&g))return 1e300;return std::pow((z[2]-op.branch.measured_alpha)/(op.branch.upper-op.branch.lower)*std::sqrt(d2),2)+g*g;};for(int k=0;k<30;++k){double l=lo+(hi-lo)/3,h=hi-(hi-lo)/3;if(cost(l)<cost(h))hi=h;else lo=l;}}
  *navigation={{"valid",true},{"kind","source_UV_nearest_true_physical_curve_RS_navigation_only"},{"station",nearest[0]},{"sensor_row",nearest[1]},{"alpha_seed",op.branch.measured_alpha},{"UV",nearest_uv},{"source_twoD_error_px",std::sqrt(nearest_cost)},{"RS_equality_px",nearest[1]-nearest_uv[1]},{"Query_closed_claimed",false}};
 }else *navigation={{"valid",false},{"kind","no_finite_true_physical_curve_RS_navigation_found"}};
